#!/bin/bash
# Task 134-w7-m2-refs-baseline -- meshsim sim/ WORKER7 (branch sim-w7 f47b12f). TIMING FIRST: keep the box quiet while it runs.
# M2's reference side (sim/planning/sessions/WORKER7/PROMPT.md items 3 and 5), from an embedded kit (sim/ref/meshsim, the
# drivers sim/tests/ref/{M2Sort,M2Prog,FpHooks,StateFp,TraceRun}.java, sim/tests/golden-m2, W5's machine.inc):
#   1. the machine (D21: detected, recorded); KeyGen's uniform set at 64 x 65,536, checked against Quest 118's key file;
#   2. BASELINE, alone on the box, pinned to the first detected P-core CPU: the full sort p4/uniform-k128 in ref on one JVM,
#      3 runs of M2Sort (hooks off) splitting setup, boot and the counted run (L1 GO -> L2 all READY, 1,229,687 cycles);
#      then 1 run of SortTest itself timed as a whole JVM (Quest 120's 110 s measure);
#   3. golden-m2's full-size references (regen.sh ALL=1 '^sort64k': the facts, coverage, PhaseLog, fingerprints, retire
#      traces of tiles 0, 27, 63), 3 at a time, every file into $DATA/w7-golden-m2/f47b12f (staged, then moved; COMPLETE);
#   4. regen.sh --check of every local reference (regs, wfi, a2a, NetTest, EngineTest, the 16K sort): all SAME expected.
# Expected ~40 min. Writes only results/134-w7-m2-refs-baseline/ and $DATA/w7-golden-m2/. Scratch /tmp/w7-134, removed
# first and at the end. Safe to re-run (a complete $DATA copy is replaced only after the new one is complete).
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/134-w7-m2-refs-baseline; mkdir -p "$RES"
W=/tmp/w7-134; rm -rf "$W"; mkdir -p "$W"; trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "9416c3d31aa96f4261c277bf9b7373bc5047cb3bc77b79f16a72374dcf5a0daa" ] || { echo "kit sha256 mismatch"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
DATA=$HOME/data
{ mkdir -p "$DATA" && touch "$DATA/.writable" && rm -f "$DATA/.writable"; } 2>/dev/null || DATA=$REPO/data
DEST=$DATA/w7-golden-m2/f47b12f; echo "$DEST" > "$RES/data_path.txt"
FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
{
SIM=$W/kit/sim; G=$SIM/tests/golden-m2
sec "machine (D21)"
. "$SIM/planning/sessions/WORKER5-tasks/machine.inc"
machine_record "$RES/machine.txt"
CPU=${P_ONE%%,*}; echo "pinned to CPU $CPU (the first of P_ONE $P_ONE)"; java -version 2>&1 | head -1; uptime

sec "build: a scratch copy of sim/ref/meshsim with golden-m2's images, ref and the drivers (as regen.sh builds them)"
M=$W/m; C=$W/cls; mkdir -p "$M" "$C"
(cd "$SIM/ref/meshsim" && tar cf - --exclude=./build --exclude=./sw/build --exclude=./sw/ext/sort/build --exclude=./results .) | (cd "$M" && tar xf -)
mkdir -p "$M/sw/build" "$M/sw/ext/sort/build"; cp "$G"/images/sort.* "$M/sw/ext/sort/build/"; rm -f "$M/sw/ext/sort/build/MANIFEST.md"
javac -nowarn -d "$C" "$M"/src/*.java > "$RES/build.log" 2>&1 || verdict "javac ref" FAIL
grep -v '^#' "$M/test/PENDING" | awk 'NF{print "'"$M"'/test/"$1}' > "$W/pending.txt"
javac -nowarn -d "$C" -cp "$C" $(ls "$M"/test/*.java | grep -v -x -F -f "$W/pending.txt") >> "$RES/build.log" 2>&1 || verdict "javac ref tests" FAIL
javac -nowarn -d "$C" -cp "$C" "$SIM"/tests/ref/{TraceRun,StateFp,FpHooks,M2Sort,M2Prog}.java >> "$RES/build.log" 2>&1 || verdict "javac drivers" FAIL
(cd "$M" && java -Xmx2g -cp "$C" KeyGen "$W/keys" --n 65536 --only uniform) > /dev/null 2>&1
K=$W/keys/uniform.keys; KH=$(sha256sum < "$K" | cut -c1-64); echo "keys-65536/uniform.keys $KH"
[ "$KH" = a7636b687a6db39cac8fbf63c2f16f686fd1ce858fe8a7ed5d98621e452c9b7a ] && verdict "the key file is Quest 118's" PASS || verdict "the key file is Quest 118's" FAIL

sec "2. baseline: M2Sort x 3 (hooks off), then SortTest as a whole JVM, each alone on CPU $CPU"
for r in 1 2 3; do
  (cd "$M" && taskset -c $CPU java -Xmx6g -cp "$C" M2Sort keys="$K") > "$RES/baseline-m2sort-$r.log" 2>&1
  grep -E '^sort |^verify|^timing' "$RES/baseline-m2sort-$r.log"
  grep -q 'TOTAL 1229687 cycles' "$RES/baseline-m2sort-$r.log" && grep -q ': PASS' "$RES/baseline-m2sort-$r.log" && verdict "M2Sort run $r: 1,229,687 cycles, verified" PASS || verdict "M2Sort run $r" FAIL
done
a=$(date +%s.%N)
(cd "$M" && taskset -c $CPU java -Xmx6g -cp "$C" SortTest -1 run label=p4/uniform-k128 keys="$K" fmt=k128 ready=8) > "$RES/baseline-sorttest.log" 2>&1
b=$(date +%s.%N); echo "SortTest whole JVM: $(echo "$b - $a" | bc) s" | tee "$RES/baseline-sorttest-wall.txt"
grep -q 'TOTAL 1,229,687 cycles' "$RES/baseline-sorttest.log" && grep -q '0 failed' "$RES/baseline-sorttest.log" && verdict "SortTest: 1,229,687 cycles, 0 failed" PASS || verdict "SortTest" FAIL

sec "3. the full-size references (regen.sh ALL=1 '^sort64k', 3 at a time) into $DEST"
rm -rf "$DEST.staging"; mkdir -p "$DEST.staging"
(cd "$G" && KEEP="$DEST.staging" ALL=1 P=3 JX=-Xmx5g ./regen.sh '^sort64k') > "$RES/regen-full.log" 2>&1; tail -3 "$RES/regen-full.log"
for f in sort64k.out sort64k.cover.csv sort64k.phases.csv HASHES; do cp "$G/$f" "$RES/" 2>/dev/null || verdict "$f made" FAIL; done
(cd "$DEST.staging" && sha256sum *) > "$RES/full-files.sha256"; cat "$RES/full-files.sha256"; du -sh "$DEST.staging"
grep -q 'TOTAL 1229687 cycles' "$RES/sort64k.out" && grep -q ': PASS' "$RES/sort64k.out" && verdict "sort64k: 1,229,687 cycles, verified" PASS || verdict "sort64k" FAIL
n=$(ls "$DEST.staging" | wc -l); [ "$n" -ge 13 ] && verdict "sort64k: $n files kept" PASS || verdict "sort64k files ($n)" FAIL
cp "$RES/full-files.sha256" "$DEST.staging/COMPLETE"; rm -rf "$DEST"; mv "$DEST.staging" "$DEST"

sec "4. regen.sh --check of every local reference"
(cd "$G" && P=8 ./regen.sh --check) > "$RES/regen-check.log" 2>&1; tail -5 "$RES/regen-check.log"
grep -q 'all SAME' "$RES/regen-check.log" && verdict "regen.sh --check (local references)" PASS || verdict "regen.sh --check" FAIL

sec "summary"; grep '^VERDICT' "$RES/run.log" 2>/dev/null
} 2>&1 | tee "$RES/run.log"
grep -q '^VERDICT .*: FAIL' "$RES/run.log" && exit 1
exit 0
